mapper.select:
select distinct sdl.ITEM_CODE id, sdl.ITEM_VALUE text from SYS_DATADICT_LIST sdl inner join SYS_DATADICT_LIST_LINK sdll on sdl.ITEM_CODE = sdll.ITEM_CODE
and sdll.LINKED_DICT_CODE = #{dict_code_parent}
and sdl.DICT_CODE = #{dict_code_child} and sdll.DICT_CODE = #{dict_code_child}
and TRIM(sdll.LINKED_ITEM_CODE) = TRIM(#{item_code_parent})
sdl.ITEM_VALUE like concat_ws('','%', #{search} ,'%')
ORDER BY sdl.ITEM_CODE asc

SELECT IFNULL(SUM(A.O_AMT),0) FROM BOK_BALANCE A,BOK_SUBJECT B,BOK_BOOKSET C WHERE A.BOOKSET_ID = C.BOOKSET_ID AND B.BOOKSET_ID = C.BOOKSET_ID_TMPL AND A.SUBJECT_NO = B.SUBJECT_NO AND B.BASE_SUBJECT_NATURE = 'XJ' AND A.SUBJECT_LEVEL = '1'
AND A.BOOKSET_ID in
#{item}
AND DATE_FORMAT(A.BALANCE_DATE,'%Y-%m-%d') = #{mdate,jdbcType=VARCHAR}

SELECT IFNULL(SUM(A.O_AMT),0) FROM BOK_BALANCE A,BOK_SUBJECT B,BOK_BOOKSET C WHERE A.BOOKSET_ID = C.BOOKSET_ID AND B.BOOKSET_ID = C.BOOKSET_ID_TMPL AND A.SUBJECT_NO = B.SUBJECT_NO AND B.BASE_SUBJECT_NATURE = 'XJ' AND A.SUBJECT_LEVEL = '1'
AND A.BOOKSET_ID in
#{item}
AND DATE_FORMAT(A.BALANCE_DATE,'%Y-%m-%d') = #{mdate,jdbcType=VARCHAR}

SELECT IFNULL(SUM(A.O_HAPPEN_AMT),0) FROM TRD_VOUCH_DEAL_DETAIL A,BOK_SUBJECT B,BOK_BOOKSET C,TRD_VOUCH_DEAL D WHERE 1=1
AND A.BOOKSET_ID in
#{item}
AND C.BOOKSET_ID = A.BOOKSET_ID AND B.BOOKSET_ID = C.BOOKSET_ID_TMPL AND A.SUBJECT_NO = B.SUBJECT_NO AND B.BASE_SUBJECT_NATURE = 'XJ' AND D.TRADE_ID = A.TRADE_ID AND A.CD_FLAG = #{crdrFlg,jdbcType=VARCHAR} AND DATE_FORMAT(D.BOOK_DATE,'%Y-%m-%d') >= #{vdate,jdbcType=VARCHAR} AND DATE_FORMAT(D.BOOK_DATE,'%Y-%m-%d') <= #{mdate,jdbcType=VARCHAR}
